 W(1, CREATE, 'Print 5 evenly spaced numbers from 0 to 100 (both included) with `np.linspace`.', NP, NP + 'print(np.linspace(0, 100, 5))', "`linspace(start, stop, how_many)` includes the stop value and spaces the numbers evenly."),
